    std::string line;
    while (getline(inFile, line)) {
        std::istringstream lineStream(line);
        std::string word;

        while (lineStream >> word) {
            if (word == wordToSearch) {
                wordCount++;
            }
        }
    }

    inFile.close();
    std::cout << "The word \"" << wordToSearch << "\" appears " << wordCount << " times in the file " << fileName << std::endl;

    return 0;
}
