```csharp
using System;
using System.Collections.Generic;

namespace QuickSort
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] arr = { 10, 80, 30, 90, 40, 50, 70 };
            int[] sortedArr = QuickSort(arr, 0, arr.Length - 1);

